package com.hibernate.ecommerce.controller;import com.hibernate.ecommerce.dto.ClientDTO;import com.hibernate.ecommerce.service.IClientService;import jakarta.validation.Valid;import jakarta.validation.constraints.Positive;import org.springframework.http.ResponseEntity;import org.springframework.web.bind.annotation.*;import org.springframework.web.servlet.support.ServletUriComponentsBuilder;import java.net.URI;import java.util.List;@RestController@RequestMapping("/v1/api/client")public class ClientController {    private final IClientService iClientService;    public ClientController(IClientService iClientService) {        this.iClientService = iClientService;    }    @PostMapping("/insert")    public ResponseEntity<ClientDTO> insertClient(@Valid @RequestBody ClientDTO dto){        ClientDTO saved = iClientService.addClient(dto);        URI location = ServletUriComponentsBuilder                .fromCurrentRequest()                .path("/{id}")                .buildAndExpand(saved.getId())                .toUri();        return ResponseEntity.created(location).body(saved);    }    @GetMapping("/search/{id}")    public ResponseEntity<ClientDTO> findClientById(@PathVariable @Positive Long id){        return ResponseEntity.ok(iClientService.findClientById(id));    }    @GetMapping("/search")    public ResponseEntity<List<ClientDTO>> findAllClient(){        return ResponseEntity.ok(iClientService.findAllClient());    }    @PutMapping("/update/{id}")    public ResponseEntity<ClientDTO> updateClient(@PathVariable @Positive Long id, @Valid @RequestBody ClientDTO dto){        return ResponseEntity.ok(iClientService.updateClient(id, dto));    }    @DeleteMapping("/delete/{id}")    public ResponseEntity<Void> deleteClientById(@PathVariable @Positive Long id){        iClientService.deleteClient(id);        return ResponseEntity.noContent().build();    }}